package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_HexInteger() {
        // hexDigits = 2 (<= 8) -> Integer
        assertTrue(NumberUtils.createNumber("0x12").equals(28));
        assertTrue(NumberUtils.createNumber("0X12").equals(28));
        assertTrue(NumberUtils.createNumber("#12").equals(18));
        assertTrue(NumberUtils.createNumber("-#12").equals(-18));
        assertTrue(NumberUtils.createNumber("-0x12").equals(-18));
        assertTrue(NumberUtils.createNumber("-0X12").equals(-18));
    }

    @Test
    public void testCreateNumber_HexLong() {
        // hexDigits = 9 (> 8 and <= 16) -> Long
        // "0x123456789" -> 9 digits
        Number n = NumberUtils.createNumber("0x123456789");
        assertTrue(n instanceof Long);
    }

    @Test
    public void testCreateNumber_HexBigInteger() {
        // hexDigits = 17 (> 16) -> BigInteger
        Number n = NumberUtils.createNumber("0x12345678901234567");
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Integer() {
        assertTrue(NumberUtils.createNumber("123").equals(123));
    }

    @Test
    public void testCreateNumber_Long() {
        // Larger than Integer.MAX_VALUE
        Number n = NumberUtils.createNumber("3000000000");
        assertTrue(n instanceof Long);
        assertEquals(3000000000L, n.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        // Extremely large
        Number n = NumberUtils.createNumber("9999999999999999999999999999999999");
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Float() {
        // numDecimals <= 7
        Number n = NumberUtils.createNumber("1.234567");
        assertTrue(n instanceof Float);
    }

    @Test
    public void testCreateNumber_Double() {
        // numDecimals <= 16
        Number n = NumberUtils.createNumber("1.234567890123456");
        assertTrue(n instanceof Double);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // numDecimals > 16
        Number n = NumberUtils.createNumber("1.234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_Exponent() {
        // 1e10 -> Double/BigDecimal logic
        Number n = NumberUtils.createNumber("1e10");
        assertNotNull(n);
    }

    @Test
    public void testCreateNumber_DecimalWithExponent() {
        Number n = NumberUtils.createNumber("1.2e10");
        assertNotNull(n);
    }

    @Test
    public void testCreateNumber_SuffixFloat() {
        Number n = NumberUtils.createNumber("1.23F");
        assertTrue(n instanceof Float);
    }

    @Test
    public void testCreateNumber_SuffixDouble() {
        Number n = NumberUtils.createNumber("1.23D");
        assertTrue(n instanceof Double);
    }

    @Test
    public void testCreateNumber_SuffixInvalid() {
        // The L branch in the code has a 'false' condition in the if statement 
        // which makes it practically unreachable for valid numbers, 
        // but we test the fallthrough/exception.
        try {
            NumberUtils.createNumber("123L");
        } catch (NumberFormatException e) {
            // Expected based on the 'false' logic in code
        }
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() {
        NumberUtils.createNumber("123X");
    }

    @Test
    public void testCreateNumber_AllZeros() {
        // Tests the allZeros logic used in precision checks
        Number n = NumberUtils.createNumber("0.0000000");
        assertNotNull(n);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_BadExponentPos() {
        // Triggering the expPos < decPos check
        NumberUtils.createNumber("1e.5");
    }

    @Test
    public void testCreateNumber_FloatPrecisionLoss() {
        // If float cannot represent it precisely, it should fall to Double or BigDecimal
        // Using a number that is too large for Float but fits in Double
        Number n = NumberUtils.createNumber("1.234567890123456789E30");
        assertNotNull(n);
    }
}
